package main

import (
  "fmt"
  "net/http"
  "io/ioutil"
)

func main() {
  reqUrl := "https://globalname.melissadata.net/V3/WEB/GlobalName/doGlobalName"
  req, err := http.NewRequest("GET", reqUrl, nil)

  query := req.URL.Query()
  query.Add("format", "JSON")
  query.Add("id", "{REPLACE-WITH-YOUR-LICENSE-KEY}")
  query.Add("full", "Doktor Enna Schäfer")
  query.Add("ctry", "DE")
  req.URL.RawQuery = query.Encode()

  if err != nil {
    panic(err)
  }
  req.Header.Add("Accept", "*/*")
  req.Header.Add("Content-Type", "application/json")
  res, err := http.DefaultClient.Do(req)
  if err != nil {
    panic(err)
  }
  defer res.Body.Close()
  body, err := ioutil.ReadAll(res.Body)
  if err != nil {
    panic(err)
  }

  fmt.Println(res)
  fmt.Println(string(body))
}
